import torch

def run(x, return_inverse, return_counts):
    return torch.unique_consecutive(x, return_inverse=return_inverse, return_counts=return_counts)

def _dtype_from_context(ctx, name):
    return getattr(torch, ctx[f"{name}__dtype"])

def gen_inputs(ctx, device):
    value = torch.randint(-5, 5, ctx["x__shape"], device=device)
    return {"x": value.to(_dtype_from_context(ctx, "x"))}
